changeSet.sql:
CREATE TABLE app_user (
    id uuid PRIMARY KEY,
    display_name varchar(100) NOT NULL
);

CREATE TABLE sport_type (
    id serial PRIMARY KEY,
    name varchar(50) NOT NULL UNIQUE
);

INSERT INTO sport_type (name) VALUES
    ('Бадминтон'),
    ('Шахматы'),
    ('Волейбол'),
    ('Настольный теннис');

CREATE TABLE club (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(200) NOT NULL,
    sport_type_id int NOT NULL REFERENCES sport_type(id),
    description varchar(2000),
    owner_id uuid NOT NULL REFERENCES app_user(id),
    closed boolean NOT NULL DEFAULT false,
    created_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX idx_club_owner ON club(owner_id);

CREATE TABLE club_member (
    club_id uuid NOT NULL REFERENCES club(id),
    user_id uuid NOT NULL REFERENCES app_user(id),
    PRIMARY KEY (club_id, user_id)
);
CREATE INDEX idx_club_member_user ON club_member(user_id);

CREATE TABLE invitation (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    club_id uuid NOT NULL REFERENCES club(id),
    name varchar(200) NOT NULL,
    active boolean NOT NULL DEFAULT true,
    created_by uuid NOT NULL REFERENCES app_user(id),
    created_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX idx_invitation_club ON invitation(club_id);

CREATE TABLE training (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    club_id uuid NOT NULL REFERENCES club(id),
    day_of_week int NOT NULL,
    start_time time NOT NULL,
    end_time time NOT NULL,
    max_players int NOT NULL
);
CREATE INDEX idx_training_club ON training(club_id);

CREATE TABLE training_slot (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    training_id uuid NOT NULL REFERENCES training(id),
    slot_date date NOT NULL,
    CONSTRAINT uq_slot_training_date UNIQUE (training_id, slot_date)
);
CREATE INDEX idx_training_slot_training ON training_slot(training_id);

CREATE TABLE friend (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES app_user(id),
    name varchar(100) NOT NULL,
    created_at timestamp NOT NULL DEFAULT now(),
    CONSTRAINT uq_friend_user_name UNIQUE (user_id, name)
);
CREATE INDEX idx_friend_user ON friend(user_id);

CREATE TABLE training_enrollment (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slot_id uuid NOT NULL REFERENCES training_slot(id),
    user_id uuid REFERENCES app_user(id),
    friend_id uuid REFERENCES friend(id) ON DELETE CASCADE,
    enrolled_by uuid REFERENCES app_user(id),
    enrolled_at timestamp NOT NULL DEFAULT now(),
    CONSTRAINT uq_training_enrollment_slot_user UNIQUE (slot_id, user_id),
    CONSTRAINT uq_training_enrollment_slot_friend UNIQUE (slot_id, friend_id),
    CONSTRAINT chk_training_enrollment_target CHECK (num_nonnulls(user_id, friend_id) = 1)
);
CREATE INDEX idx_training_enrollment_user ON training_enrollment(user_id);

CREATE TABLE training_comment (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slot_id uuid NOT NULL REFERENCES training_slot(id),
    user_id uuid NOT NULL REFERENCES app_user(id),
    text text NOT NULL,
    created_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX idx_training_comment_slot ON training_comment(slot_id);

CREATE TABLE visit_history (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    club_id uuid NOT NULL REFERENCES club(id),
    user_id uuid NOT NULL REFERENCES app_user(id),
    slot_date date NOT NULL,
    sport_type varchar(50) NOT NULL,
    recorded_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX idx_visit_history_club ON visit_history(club_id);
CREATE INDEX idx_visit_history_user ON visit_history(user_id);
CREATE INDEX idx_visit_history_date ON visit_history(slot_date);

CREATE TABLE invitation_history (
    invitation_id uuid NOT NULL REFERENCES invitation(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES app_user(id),
    joined_at timestamp NOT NULL DEFAULT now(),
    PRIMARY KEY (invitation_id, user_id)
);
